#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1;
const int REAC = -2;
const int BAD_REAC = -3;
const int CAPSULE = ROOM;

int maze[MAXN][MAXN], capsuleCount[MAXN][MAXN];
int tox[61][MAXN][MAXN];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

struct Coord {
    int x, y, amount;
    Coord(int a = 0, int b = 0, int c = 0) : x(a), y(b), amount(c) {}
};

vector<Coord> civilians, capsules;

bool passable(int x, int y, int n) {
    return x >= 0 && x < n && y >= 0 && y < n && maze[x][y] == ROOM;
}

int typeOf(char c) {
    if (c >= '0' && c <= '9') return ROOM;
    if (c == 'Y') return REAC;
    if (c == 'Z') return BAD_REAC;
    return -1;
}

int amtOf(char c) {
    return c - '0';
}

void spread(int x, int y, int T, int n) {
    tox[0][x][y] = 1;

    for (int t = 1; t <= T; ++t) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (tox[t - 1][i][j]) {
                    tox[t][i][j] = 1;

                    for (int d = 0; d < 4; ++d) {
                        int nx = i + dx[d];
                        int ny = j + dy[d];

                        if (passable(nx, ny, n)) {
                            tox[t][nx][ny] = 1;
                        }
                    }
                }
            }
        }
    }
}

int pathTime(const Coord &a, const Coord &b, int n, int T) {
    vector<bitset<MAXN>> used(n);
    queue<pair<int, Coord>> q;
    q.push({0, a});
    used[a.x][a.y] = 1;

    while (!q.empty()) {
        int t = q.front().first;
        Coord cur = q.front().second;
        q.pop();

        if (cur.x == b.x && cur.y == b.y) return t;
        if (t == T) continue;
        if (tox[t][cur.x][cur.y]) continue;

        for (int d = 0; d < 4; ++d) {
            Coord nxt(cur.x + dx[d], cur.y + dy[d], 0);

            if (passable(nxt.x, nxt.y, n) && !used[nxt.x][nxt.y] && !tox[t][nxt.x][nxt.y]) {
                used[nxt.x][nxt.y] = 1;
                q.push({t + 1, nxt});
            }
        }
    }

    return 999;
}

class ResidualNet {
    int n;
    vector<vector<int>> residual;
    vector<int> visited;

public:
    ResidualNet(int _n) : n(_n), residual(_n, vector<int>(_n, 0)), visited(_n, 0) {}

    void addEdge(int u, int v, int capacity) {
        residual[u][v] += capacity;
    }

    int findPath(int u, int t, int pushed) {
        if (u == t) return pushed;

        visited[u] = 1;

        for (int v = 0; v < n; ++v) {
            if (!visited[v] && residual[u][v] > 0) {
                int got = findPath(v, t, min(pushed, residual[u][v]));

                if (got > 0) {
                    residual[u][v] -= got;
                    residual[v][u] += got;
                    return got;
                }
            }
        }

        return 0;
    }

    long long maxFlow(int s, int t) {
        long long total = 0;

        while (true) {
            fill(visited.begin(), visited.end(), 0);
            int pushed = findPath(s, t, INT_MAX);

            if (pushed == 0) break;

            total += pushed;
        }

        return total;
    }
};

int main() {
    int N, T;
    scanf(" %d %d", &N, &T);

    Coord badReactor(0, 0, 0);
    char ch;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);

            int type = typeOf(ch);
            int amount = amtOf(ch);

            maze[i][j] = type;

            if (type == ROOM && amount > 0) {
                civilians.push_back(Coord(i, j, amount));
            }

            if (type == BAD_REAC) {
                badReactor = Coord(i, j, 0);
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);

            int type = typeOf(ch);
            int amount = amtOf(ch);

            if (type == CAPSULE && amount > 0) {
                capsules.push_back(Coord(i, j, amount));
                capsuleCount[i][j] = amount;
            }
        }
    }

    ResidualNet net(MAXN);
    int source = 0;
    int sink = MAXN - 1;

    for (size_t i = 0; i < civilians.size(); ++i) {
        net.addEdge(source, (int)i * 2 + 1, civilians[i].amount);
    }

    for (size_t i = 0; i < capsules.size(); ++i) {
        net.addEdge((int)i * 2 + 2, sink, capsules[i].amount);
    }

    spread(badReactor.x, badReactor.y, T, N);

    for (size_t i = 0; i < civilians.size(); ++i) {
        for (size_t j = 0; j < capsules.size(); ++j) {
            int t = pathTime(civilians[i], capsules[j], N, T);

            if (t <= T) {
                net.addEdge((int)i * 2 + 1, (int)j * 2 + 2, 999);
            }
        }
    }

    printf("%lld\n", net.maxFlow(source, sink));
    return 0;
}
